<svelte:options immutable={true} />

<script lang="ts">import JSONRepairComponent from './repair/JSONRepairComponent.svelte';
import Modal from './Modal.svelte';
export let text;
export let onParse;
export let onRepair;
export let onApply;
export let onClose;
function handleApply(repairedText) {
    onApply(repairedText);
    onClose();
}
function handleCancel() {
    onClose();
}
</script>

<Modal {onClose} className="jse-repair-modal">
  <JSONRepairComponent
    bind:text
    {onParse}
    {onRepair}
    onApply={handleApply}
    onCancel={handleCancel}
  />
</Modal>
